          manifestJson: this.manifest.toJSON(),
          remoteFile: this.eventsFilePath(),
          plainData: eventsJsonl
        };
        const eventsUploadResult = await this.executeTaskWithFallback<UploadTaskWithEncryptParams, UploadTaskResult>(executeUploadWithEncrypt, eventsUploadParams);

        if (!eventsUploadResult.success) {
          console.error(`[WebDavSyncManager] Step 4 upload failed: ${eventsUploadResult.detail}`);
          return WebDavSyncResult.fail('增量同步失败（事件上传）', eventsUploadResult.detail);
        }
        const step4Ms = Date.now() - step4StartMs;
        console.info(`[WebDavSyncManager] Step 4 complete ms=${step4Ms}`);
      } else {
        console.info('[WebDavSyncManager] No events to upload, skipping step 4');
      }

      const totalSyncMs = Date.now() - syncStartMs;
      console.info(`[WebDavSyncManager] ==== Sync completed successfully total_ms=${totalSyncMs} ====`);
      
      // 如果事件下载被跳过（因为 MAC 校验失败），提示用户事件已重新上传
      if (eventsDownloadSkipped) {
        return WebDavSyncResult.ok('同步完成（已重新上传事件数据覆盖云端损坏文件）');
      }
      return WebDavSyncResult.ok('同步完成');
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      const stack = e instanceof Error ? e.stack : '';
      console.error(`[WebDavSyncManager] Sync failed with exception: ${msg}`);
      if (stack) {
        console.error(`[WebDavSyncManager] Stack trace: ${stack}`);
      }
      return WebDavSyncResult.fail('增量同步失败', msg);
    } finally {
      // 确保状态总是重置为 IDLE
      this.status = WebDavSyncStatus.IDLE;
      console.info('[WebDavSyncManager] Sync status reset to IDLE');
    }
  }

  /**
   * 在 TaskPool 中执行备份（后台执行，不阻塞 UI）
   */
  async backupToCloudInBackground(): Promise<WebDavSyncResult> {
    console.info('[WebDavSyncManager] ==== Starting cloud backup ====');
    const backupStartMs = Date.now();
    
    const missing = this.requireConfigured();
    if (missing !== null) {
      console.error('[WebDavSyncManager] Backup failed: not configured');
      return missing;
    }

    // 检查是否已经在同步中
    if (this.status === WebDavSyncStatus.SYNCING) {
      console.warn('[WebDavSyncManager] Backup already in progress');
      return WebDavSyncResult.fail('同步操作正在进行中', '请等待当前同步完成后再试');
    }

    this.status = WebDavSyncStatus.SYNCING;
    console.info('[WebDavSyncManager] Backup status set to SYNCING');

    // 先确保远程目录存在
    const client = this.createClient();
    const preflight = await this.preflightRemoteRoot(client);
    if (preflight !== null) {
      this.status = WebDavSyncStatus.ERROR;
      console.error(`[WebDavSyncManager] Preflight check failed: ${preflight.message}`);
      return preflight;
    }

    // yield 给 UI 线程
    await new Promise<void>((resolve) => setTimeout(resolve, 0));

    try {
      const syncManager = DataSyncManager.getInstance();

      // 导出数据（在主线程执行，需要数据库）
      console.info('[WebDavSyncManager] Exporting data from database');
      const exportStartMs = Date.now();
      const exportResult = await syncManager.exportData();
      if (!exportResult.success) {
        console.error(`[WebDavSyncManager] Export failed: ${exportResult.error}`);
        return WebDavSyncResult.fail('备份失败', exportResult.error);
      }
      const exportMs = Date.now() - exportStartMs;
      console.info(`[WebDavSyncManager] Export complete data_size=${exportResult.data.length} chars ms=${exportMs}`);

      // yield 给 UI 线程
      await new Promise<void>((resolve) => setTimeout(resolve, 0));

      // 加密和上传数据（在 TaskPool 中执行，避免阻塞 UI）
      console.info('[WebDavSyncManager] Starting encryption and upload in background');
      const uploadStartMs = Date.now();
      const params: BackupTaskWithEncryptParams = {
        endpoint: this.settings.endpoint,
        username: this.settings.username,
        password: this.settings.password,
        syncPassword: this.settings.syncPassword,
        remoteRoot: this.settings.remoteRoot,
        manifestJson: this.manifest.toJSON(),
        backupFilePath: this.backupFilePath(),
        plainData: exportResult.data
      };

      const result = await this.executeTaskWithFallback<BackupTaskWithEncryptParams, BackupTaskResult>(executeBackupWithEncrypt, params);
      const uploadMs = Date.now() - uploadStartMs;

      if (result.success) {
        // 备份成功后，更新本地 VersionControl 时间戳，确保本地版本号与导出数据同步
        try {
          syncManager.getVersionControl().updateTimestamp();
          console.info('[WebDavSyncManager] Local VersionControl timestamp updated after backup');
        } catch (e) {
          const errMsg = e instanceof Error ? e.message : String(e);
          console.warn(`[WebDavSyncManager] Failed to update local VersionControl: ${errMsg}`);
        }
        
        const totalBackupMs = Date.now() - backupStartMs;
        console.info(`[WebDavSyncManager] ==== Backup completed successfully total_ms=${totalBackupMs} export_ms=${exportMs} upload_ms=${uploadMs} ====`);
        return WebDavSyncResult.ok(result.message);
      } else {
        console.error(`[WebDavSyncManager] Backup failed: ${result.detail}`);
        return WebDavSyncResult.fail('备份失败', result.detail);
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      const stack = e instanceof Error ? e.stack : '';
      console.error(`[WebDavSyncManager] Backup failed with exception: ${msg}`);
      if (stack) {
        console.error(`[WebDavSyncManager] Stack trace: ${stack}`);
      }
      return WebDavSyncResult.fail('备份失败', msg);
    } finally {
      // 确保状态总是重置为 IDLE
      this.status = WebDavSyncStatus.IDLE;
      console.info('[WebDavSyncManager] Backup status reset to IDLE');
    }
  }

  // 序列化事件为 JSON Lines
  private serializeEventsJsonl(events: ReviewEventRow[]): string {
    let out = '';
    for (const e of events) {
      // 使用 Record<string, Object> 类型来避免对象字面量类型检查问题
      const obj: Record<string, Object> = {
        'id': e.id,
        'wordId': e.wordId,
        'rating': e.rating,
        'timestamp': e.timestamp,
        'prevStateJson': e.prevStateJson,
        'newStateJson': e.newStateJson,
        'errorTag': e.errorTag,
        'reflection': e.reflection,
        'scheduledDays': e.scheduledDays
      };
      out += `${JSON.stringify(obj)}\n`;
    }
    return out;
  }

  // 解析 JSON Lines
  private parseEventsJsonl(jsonl: string): ReviewEventRow[] {
    const lines = jsonl.split(/\r?\n/);
    const out: ReviewEventRow[] = [];
    for (const line of lines) {
      const s = line.trim();
      if (s.length === 0) continue;
      try {
        const obj = JSON.parse(s) as Record<string, string | number>;
        const row: ReviewEventRow = {
          id: (obj['id'] as string) ?? '',
          wordId: (obj['wordId'] as number) ?? 0,
          rating: (obj['rating'] as number) ?? 0,
          timestamp: (obj['timestamp'] as number) ?? 0,
          prevStateJson: (obj['prevStateJson'] as string) ?? '{}',
          newStateJson: (obj['newStateJson'] as string) ?? '{}',
          errorTag: (obj['errorTag'] as string) ?? '',
          reflection: (obj['reflection'] as string) ?? '',
          scheduledDays: (obj['scheduledDays'] as number) ?? 0
        };
        if (row.id.length > 0 && row.wordId > 0 && row.timestamp > 0) {
          out.push(row);
        }
      } catch (e) {
        // skip malformed line
      }
    }
    return out;
  }

  private buildIncrementalStepFailure(step: string, result: WebDavSyncResult): WebDavSyncResult {
    const detail = result.detail.length > 0 ? result.detail : result.message;
    return WebDavSyncResult.fail(`增量同步失败（${step}）`, `STEP ${step}: ${detail}`);
  }

  private async withTimeout<T>(promise: Promise<T>, ms: number, errorMsg: string): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error(errorMsg));
      }, ms);
      promise
        .then((result: T) => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch((err: Error) => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  /**
   * 尝试在 TaskPool 中执行任务，如果 TaskPool 不可用则回退到主线程执行
   * 
   * 注意：在主线程执行加密/解密/网络请求等耗时操作可能导致 UI 卡顿。
   * 仅当 TaskPool 不可用时才会使用此 fallback 方案。
   */
  private async executeTaskWithFallback<TParams extends Object, TResult>(
    taskFn: (params: TParams) => TResult | Promise<TResult>,
    params: TParams
  ): Promise<TResult> {
    try {
      return await taskpool.execute(new taskpool.Task(taskFn, params)) as TResult;
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      // 仅捕获 TaskPool 不支持的错误（匹配多种变体），其他错误继续抛出
      const isCapabilityError = msg.includes('Capability not support') ||
                                 msg.includes('Capability not supported') ||
                                 msg.includes('TaskPool not support');
      if (isCapabilityError) {
        console.warn(`[WebDavSyncManager] TaskPool not supported on this device, falling back to main thread.`);
        console.warn(`[WebDavSyncManager] UI may freeze temporarily during encryption/network operations. Error: ${msg}`);
        return await taskFn(params);
      }
      throw e instanceof Error ? e : new Error(String(e));
    }
  }

