118:    method: http.RequestMethod,
119:    path: string,
120:    headers: Record<string, string>,
121:    body: string | undefined,
122:    redirectsLeft: number,
123:    requestId: string
124:  ): Promise<WebDavResponse> {
125:    const startMs = Date.now();
126:    const request = http.createHttp();
127:
128:    const url = this.buildUrl(path);
129:    // Merge headers manually to avoid spread operator issues
130:    const allHeaders: Record<string, string> = {
131:      'Authorization': this.authHeader,
132:      'Accept': '*/*'
133:    };
134:    // Add custom headers
135:    Object.keys(headers).forEach((key: string) => {
136:      allHeaders[key] = headers[key];
137:    });
138:
139:    try {
140:      const options: http.HttpRequestOptions = {
141:        method,
142:        header: allHeaders,
143:        connectTimeout: 15000,
144:        readTimeout: 20000
145:      };
146:      if (body !== undefined && (method === http.RequestMethod.PUT || method === http.RequestMethod.POST)) {
147:        options.extraData = body;
148:      }
149:      const res = await request.request(url, options);
150:
151:      const statusCode = res.responseCode ?? 0;
152:      // Ensure res.header is treated as the correct type
153:      const resHeaders = this.normalizeHeaders(res.header as Record<string, string | string[] | number | undefined>);
154:      const raw = res.result;
155:      let bodyStr = '';
156:      if (typeof raw === 'string') {
157:        bodyStr = raw;
158:      } else if (raw instanceof ArrayBuffer) {
159:        // Decode as UTF-8-ish text (best-effort)
160:        const bytes = new Uint8Array(raw);
161:        bodyStr = '';
162:        for (const b of bytes) bodyStr += String.fromCharCode(b);
163:      } else {
164:        bodyStr = '';
165:      }
166:
167:      request.destroy();
168:      const elapsed = Date.now() - startMs;
169:      if (redirectsLeft > 0 && (statusCode === 301 || statusCode === 302 || statusCode === 303 || statusCode === 307 || statusCode === 308)) {
170:        const location = resHeaders['location'] ?? '';
171:        console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} (redirect: ${location}) in ${elapsed}ms`);
172:        if (location.length > 0) {
173:          return this.requestWithRedirect(method, location, headers, body, redirectsLeft - 1, requestId);
174:        }
175:      }
176:      console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} in ${elapsed}ms`);
177:      return { statusCode, headers: resHeaders, body: bodyStr };
178:    } catch (e) {
179:      request.destroy();
180:      const err = this.buildHttpErrorInfo(e as (object | string | number | boolean | null | undefined));
181:      const elapsed = Date.now() - startMs;
182:      console.error(`[WebDAV] ${String(method)} ${url} - ERROR ${err.code}: ${err.message} (${elapsed}ms)`);
